describe('Protected Page Access', () => {
    beforeEach(() => {
        cy.visit('/protected-page');
    });

    it('should redirect to login page when accessing protected page unauthenticated', () => {
        cy.url().should('include', '/login');
        cy.get('h1').should('contain', 'Login');
    });

    it('should not redirect to login page when accessing protected page authenticated', () => {
        cy.login('validUser', 'validPassword'); // Assuming a custom command for login
        cy.visit('/protected-page');
        cy.url().should('include', '/protected-page');
        cy.get('h1').should('contain', 'Protected Page');
    });
});
